import { createContext, createSignal, useContext, type Accessor } from "solid-js";

import { asyncLoad } from "#core/ui-next/utilities/async-load.js";

export type AudioRuleConstraint =
	| string
	| { op: undefined; value: string }
	| { op: "eq" | "neq"; value: string | number | null }
	| { op: "lt" | "lte" | "gt" | "gte" | "exists"; value: string | number }
	| { op: "in"; value: string[] };

export interface AudioRule {
	constraints?: Record<string, AudioRuleConstraint>;
	events: Record<string, string>;
	path: string;
}

export interface CompiledAudioRule {
	constraints?: Record<string, AudioRuleConstraint>;
	events: Record<string, string>;
	path: string;
}

export interface CompiledAudioRuleNode {
	rules: CompiledAudioRule[];
	children: Record<string, CompiledAudioRuleNode>;
}

export type AudioEventName =
	| "activate"
	| "focus"
	| "dragReleased"
	| "dropAccept"
	| "dropReject"
	| "press"
	| "pressError"
	| string;

/**
 * Ensure path meets the following criteria:
 * * Segments use only alphanumeric, underscore, or dash. `[azAZ19_-]`.
 * * Segments are separated by forward slashes '/'.
 * * Variables are specified at the end of the path.
 * * Variables consist of alphanumeric, understore, or dash characters `[azAZ19_-]`.
 * * Multiple variables are joined with ampersand &.
 * * Only 1 set of variables can be defined for a given path.
 * @param path
 */
function _validateAudioRulePath(_path: string) {
	//TODO
	return true;
}

export function compileAudioRules(rules: AudioRule[]) {
	const tree: CompiledAudioRuleNode = {
		rules: [],
		children: {},
	};

	// Reverse to ensure the last rules in the list get higher priority since we find the first match when triggering.
	const reverse = rules.reverse();

	for (const rule of reverse) {
		const segments = rule.path.split("/");

		let current = tree;
		for (const s of segments) {
			let child = current.children[s];

			if (child == null) {
				child = { rules: [], children: {} };
				current.children[s] = child;
			}

			current = child;
		}

		current.rules.push(rule);

		// INVESTIGATE - Do we need to sort the rules in some way (priority? specificity?)
	}

	return tree;
}

interface AudioContextValue {
	path: Accessor<string>;
	vars: Accessor<Record<string, string>>;
	tree: Accessor<CompiledAudioRuleNode>;
}

const [globalRules, setGlobalRules] = createSignal<CompiledAudioRuleNode>({ rules: [], children: {} });

export const AudioContext = createContext<AudioContextValue>({
	path: () => "",
	vars: () => ({}),
	tree: globalRules,
});

function meetsConstraint(key: string, constraint: AudioRuleConstraint, vars: Record<string, string>) {
	if (typeof constraint == "string") {
		return vars[key] == constraint;
	} else {
		if (constraint.op == null) {
			return vars[key] == constraint.value;
		} else {
			switch (constraint.op) {
				case "eq":
					return vars[key] == constraint.value;
				case "neq":
					return vars[key] != constraint.value;
				case "lt":
					return constraint.value != null ? vars[key] < constraint.value : false;
				case "lte":
					return constraint.value != null ? vars[key] <= constraint.value : false;
				case "gt":
					return constraint.value != null ? vars[key] > constraint.value : false;
				case "gte":
					return constraint.value != null ? vars[key] >= constraint.value : false;
				case "exists":
					return vars[key] != null;
				case "in":
					return constraint.value.includes(vars[key]);
				default:
					// Invalid operation!
					return false;
			}
		}
	}
}

function meetsConstraints(
	rule: CompiledAudioRule,
	vars: Record<string, string>,
	shouldLogVerbose?: UIDebugWidgetValue,
) {
	const constraints = rule.constraints;
	if (constraints == null) {
		return true;
	} else {
		return Object.entries(constraints).every(([key, value]) => {
			const result = meetsConstraint(key, value, vars);
			if (shouldLogVerbose != null && shouldLogVerbose) {
				console.log(
					`-- Constraint ${key} ${typeof value === "string" ? "eq" : value.op} ${typeof value === "string" ? value : value.value} -> ${result}`,
				);
			}
			return result;
		});
	}
}

const audioVariableRegex = /{(\w+)}/g;
export const useAudio = (localSegment?: string) => {
	const ctx = useContext(AudioContext);

	const trigger = (
		segmentOrEventName: string | AudioEventName,
		eventNameOrVars?: AudioEventName | Record<string, string>,
		optionalVars?: Record<string, string>,
	) => {
		const segment = typeof eventNameOrVars === "string" ? segmentOrEventName : null;
		const eventName = typeof eventNameOrVars === "string" ? eventNameOrVars : segmentOrEventName;
		const localVars = typeof eventNameOrVars === "object" ? eventNameOrVars : optionalVars;

		const path = ctx.path();
		const vars = localVars != null ? { ...ctx.vars(), ...localVars } : ctx.vars();

		// Determine the target path
		const targetPath = [path, localSegment, segment].filter((p) => p).join("/");
		const segments = targetPath.split("/");

		// Walk the Tree
		let current = ctx.tree();
		for (const seg of segments) {
			if (current.children[seg]) {
				current = current.children[seg];
			} else {
				// This condition would occur if the UI is providing more context than what the audio rules define.
				// For example, if the rules only define "Button" but the UI is triggering "Button/Contextual", then
				// we would hit this condition. In this case, we should stop looking for more specific matches and
				// just evaluate the rules at the current level since they may be designed to be generic enough to handle various contexts.
			}
		}

		const shouldLogVerbose = UI.Debug.getWidgetValue("logAudioRuleConstraintMatching");

		// Find the first match that meets the constraints (assuming rules is descending order!)
		const match = current.rules.find((r) => meetsConstraints(r, vars, shouldLogVerbose));

		if (match?.events[eventName]) {
			const sound = match.events[eventName];

			// Resolve dynamic templates like "play-button-{leader}" -> "play-button-LEADER_ADA_LOVELACE"
			const tag = sound.replace(audioVariableRegex, (_, k) => vars[k] || k);

			const shouldLog = UI.Debug.getWidgetValue("logMatchedAudioTriggers");
			if (shouldLog != null && shouldLog) {
				const strVars = Object.entries(vars)
					.map((entry) => `${entry[0]}=${entry[1]}`)
					.join("&");

				console.log(`${targetPath}[${strVars}]:${eventName} -> ${tag} (${match.path})`);
			}

			if (tag != null && tag != "") {
				UI.sendAudioEvent(tag);
			}
		} else {
			const shouldLog = UI.Debug.getWidgetValue("logUnmatchedAudioTriggers");
			if (shouldLog != null && shouldLog) {
				const strVars = Object.entries(vars)
					.map((entry) => `${entry[0]}=${entry[1]}`)
					.join("&");

				console.log(`${targetPath}[${strVars}]:${eventName} -> No Match`);
			}
		}
	};

	return trigger;
};

// #region Load Global Audio Rules
engine.whenReady.then(async () => {
	// Obtain the rules via the modding framework.
	const audioRules = Modding.getAudioRulesUrls();

	const rules = (await Promise.all(audioRules.map(asyncLoad))).flatMap((result) => JSON.parse(result) as AudioRule[]);

	setGlobalRules(compileAudioRules(rules));
});
// #endregion

